package sfc

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"

	"github.com/ethereum/go-ethereum/common/hexutil"
	"github.com/ethereum/go-ethereum/log"
)

// GetPatch10ContractBin returns the Cycle-165 lockup-preservation SFC bytecode
// re-flashed by the SfcV2Patch10 upgrade. It is distinct from the historical
// Patch4..Patch9 accessors so each sealed testnet re-flash remains
// reproducible, while fresh SfcV2 activations consume this bytecode through
// GetLatestContractBin().
//
// Cycle-165 source: VinuChain/vinuchain-lists contracts/vinuchain/SFC.sol.
// Compile it with the pinned toolchain, byte-for-byte:
//
//	solc 0.5.17+commit.d19bba13 --optimize --optimize-runs=10000 \
//	     --evm-version=istanbul
//
// Delta from Cycle-164 (SfcV2Patch9): fixes the chunked-settlement lockup
// destruction. Cycle-164's _stashRewards deleted getLockupInfo /
// getStashedLockupRewards on a wall-clock-only condition (!isLockedUp), so
// the FIRST partial claim after a lockup expired deleted the record and every
// later 100-epoch chunk was scaled at the unlocked rate instead of the lockup
// rate (measured on live mainnet state: ~394k VC across 42 delegations, worst
// case 48% of the owed amount; reproduced on a live-testnet fork where claim 2
// paid 2,017 VC under Cycle-164 vs 3,242 VC under Cycle-165). Three changes,
// no storage-layout change (verified identical to Cycle-164 slot-for-slot):
//
//	(1) _stashRewards deletes the lockup record only when the lockup is
//	    expired AND safeCursor >= payableEpoch (fully settled), reproducing
//	    V1's single-sweep accounting. A retained expired record cannot
//	    over-pay: _newRewardsUpTo caps lockup scaling at _highestLockupEpoch,
//	    and every current-state read (isLockedUp, getLockedStake,
//	    getUnlockedStake, unlockStake, snapshot lockedSelfStake) is
//	    wall-clock guarded.
//	(2) _lockStake requires full settlement before mutating an existing
//	    lockup record, since fromEpoch/duration/lockedStake are scaling
//	    inputs for the not-yet-swept locked window.
//	(3) restakeRewards requires the same for locked positions, which grow
//	    ld.lockedStake mid-sweep.
//	(4) _stashRewards reports cursor movement as progress, so the external
//	    stashRewards call succeeds through a zero-reward 100-epoch window
//	    instead of reverting "nothing to stash" and rolling back its own
//	    cursor advance — without this, settlement (and therefore the new
//	    relock/restake gates) could strand behind an empty window.
//
// undelegate is deliberately NOT gated - it is the fund-escape path and must
// never be blocked behind a corruption-stalled cursor.
//
// Validity of the compiled asset is enforced at opera binary startup via
// EnforcePatch10StartupCheck.
func GetPatch10ContractBin() []byte {
	return patch10ContractBin
}

// EnforcePatch10StartupCheck validates the compiled-in Patch10 bytecode at
// binary startup. A build whose Patch10 bytes are placeholder, all zero, too
// short, or byte-identical to Patch8/Patch9 refuses to start rather than
// reaching the on-chain re-flash block with an invalid asset.
func EnforcePatch10StartupCheck() {
	if err := validatePatch10Bytecode(patch10ContractBin); err != nil {
		log.Crit("SfcV2Patch10 bytecode asset is invalid - the binary must not start with this build. Recompile SFC from vinuchain-lists and replace sfc_patch10_bytecode.go", "err", err)
	}
}

var patch10DeadbeefSentinel = []byte{0xde, 0xad, 0xbe, 0xef}

// patch10ContractBin is the Cycle-165 lockup-preservation SFC runtime bytecode.
//
// Compiled from VinuChain/vinuchain-lists contracts/vinuchain/SFC.sol with the pinned
// toolchain, byte-for-byte reproducible (SFC contract, runtime part):
//
//	solc 0.5.17+commit.d19bba13 --optimize --optimize-runs=10000 --evm-version=istanbul \
//	     --bin-runtime contracts/vinuchain/SFC.sol
//
// Provenance - recompute and confirm byte-identical in the official release build (as
// every prior SfcV2Patch cycle was) and add a Cycle-165 row to deployment-log.md SFC
// Patch History BEFORE flashing to any live network:
//
//	Size:             48757 bytes
//	raw-bytes sha256: 134a508b13d46647052b64f8d6691f0b939d2afaa0fa400882c6653a40a77887
var patch10ContractBin = hexutil.MustDecode("")

// minRealPatch10BytecodeLen mirrors the prior patches' floor: a real compiled
// SFC is ~48k bytes; anything below 40000 is a placeholder or a truncated blob.
const minRealPatch10BytecodeLen = 40000

// validatePatch10Bytecode returns a non-nil error if the argument is not a
// plausible real compiled SFC, so neither EnforcePatch10StartupCheck nor any
// future release can ship the sentinel bytes in place of a real compile.
func validatePatch10Bytecode(code []byte) error {
	if len(code) == 0 {
		return errPatch10Empty
	}
	if len(code) < minRealPatch10BytecodeLen {
		return errPatch10TooShort
	}
	if len(code) >= len(patch10DeadbeefSentinel) && bytes.Equal(code[:len(patch10DeadbeefSentinel)], patch10DeadbeefSentinel) {
		return errPatch10Sentinel
	}
	allZero := true
	for _, b := range code {
		if b != 0 {
			allZero = false
			break
		}
	}
	if allZero {
		return errPatch10AllZero
	}
	if bytes.Equal(code, GetPatch8ContractBin()) {
		return errPatch10EqualsPatch8
	}
	if bytes.Equal(code, GetPatch9ContractBin()) {
		return errPatch10EqualsPatch9
	}
	// Hardening beyond the prior patches' plausibility checks: pin the exact
	// compile. The Cycle-165 build is byte-for-byte reproducible from the
	// pinned toolchain (proven by recompiling the Cycle-164 baseline to its
	// live on-chain hash first), so any legitimate rebuild produces exactly
	// these bytes — and anything else in this slot is the wrong blob, which
	// this check turns from a silent consensus divergence into a refused boot.
	// A future Cycle-166 updates this constant together with the blob.
	if sum := sha256.Sum256(code); hex.EncodeToString(sum[:]) != patch10ExpectedSHA256 {
		return errPatch10WrongDigest
	}
	return nil
}

// patch10ExpectedSHA256 pins the exact Cycle-165 compile
// (solc 0.5.17+commit.d19bba13, --optimize --optimize-runs=10000
// --evm-version=istanbul, runtime part, 48,757 bytes).
const patch10ExpectedSHA256 = "134a508b13d46647052b64f8d6691f0b939d2afaa0fa400882c6653a40a77887"

type patch10Error string

func (e patch10Error) Error() string { return string(e) }

const (
	errPatch10Empty        patch10Error = "patch10 bytecode is empty"
	errPatch10TooShort     patch10Error = "patch10 bytecode shorter than minimum SFC size - placeholder not replaced"
	errPatch10Sentinel     patch10Error = "patch10 bytecode begins with deadbeef sentinel - placeholder not replaced"
	errPatch10AllZero      patch10Error = "patch10 bytecode is all zeros"
	errPatch10EqualsPatch8 patch10Error = "SfcV2Patch10 bytecode is byte-identical to Patch8 (Cycle-163 self-service-reactivation) - the Patch10 re-flash would no-op on chain and the lockup-preservation fix would not deploy"
	errPatch10EqualsPatch9 patch10Error = "SfcV2Patch10 bytecode is byte-identical to Patch9 (Cycle-164 two-reward-fix) - the Patch10 re-flash would no-op on chain and the lockup-preservation fix would not deploy"
	errPatch10WrongDigest  patch10Error = "SfcV2Patch10 bytecode sha256 does not match the pinned Cycle-165 compile - the wrong blob is in the slot; recompile SFC from vinuchain-lists with the pinned toolchain"
)
